def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0

    if not alive_opponents:
        if hp <= 2 or no_water_days >= 1:
            return min(budget, 35)
        return min(budget, 18)

    prev_bids = []
    desperate_count = 0
    rich_count = 0
    for opp in alive_opponents:
        if opp.get('budget', 0) >= DAILY_SALARY * 2:
            rich_count += 1
        if opp.get('hp', 10) <= 2 or opp.get('no_water_days', 0) >= 1:
            desperate_count += 1
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            prev_bids.append(prev.get('bid', 0))

    if prev_bids:
        highest_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / len(prev_bids)
    else:
        highest_prev = 0
        avg_prev = 0

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0
    if scarcity > 1:
        scarcity = 1

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 2

    if supply <= WATER_REQ:
        urgency += 2
    elif supply <= WATER_REQ + 4:
        urgency += 1

    pressure = 0
    if highest_prev >= 60:
        pressure = 3
    elif highest_prev >= 45:
        pressure = 2
    elif highest_prev >= 25:
        pressure = 1

    base = 20
    if supply >= 22:
        base = 16
    elif supply <= 17:
        base = 26

    bid = base
    bid += urgency * 8
    bid += pressure * 6
    bid += scarcity * 8
    bid += desperate_count * 2
    bid += min(rich_count, 2) * 2

    if highest_prev > 0:
        target = highest_prev + 1.5
        if urgency >= 4:
            bid = max(bid, target)
        elif pressure >= 2:
            bid = max(bid, highest_prev * 0.92)
        else:
            bid = max(bid, avg_prev + 2)

    max_safe = DAILY_SALARY * 0.95
    if urgency <= 1 and pressure == 0 and supply >= 22:
        max_safe = DAILY_SALARY * 0.45
    elif urgency >= 5:
        max_safe = DAILY_SALARY * 1.15
    elif urgency >= 3:
        max_safe = DAILY_SALARY * 1.0

    if budget < DAILY_SALARY:
        max_safe = min(max_safe, budget * 0.85 + 5)

    bid = min(bid, max_safe)
    bid = min(bid, budget)

    if hp <= 2 or no_water_days >= 2:
        bid = max(bid, min(budget, 62))
    elif hp <= 3 and pressure >= 2:
        bid = max(bid, min(budget, highest_prev + 2 if highest_prev > 0 else 52))

    if bid < 0:
        bid = 0

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    budget = float(my_status.get('budget', 0.0))
    hp = float(my_status.get('hp', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opponents.append((opp_id, opp))

    # Baseline bid: ensure we can pay while not risking bankruptcy.
    # If we're already in trouble (low hp or many no-water days), bid higher.
    trouble = (hp <= 2.0) or (no_water_days >= 2)

    # Read yesterday's behavior from previous_trace (immediate reaction only)
    prev_bids = []
    for _, opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if isinstance(prev, dict) and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev['bid']))
            except Exception:
                pass

    # If no info, bid based on our status and today's supply.
    if not prev_bids:
        if trouble:
            target = DAILY_SALARY * 0.85
        else:
            # If supply is near lower bound, increase bid; otherwise keep moderate.
            if supply <= (MIN_SUPPLY + 1.0):
                target = DAILY_SALARY * 0.65
            else:
                target = DAILY_SALARY * 0.5
        return max(0.0, min(budget, target))

    highest_prev_bid = max(prev_bids)

    # If opponents were bidding very high yesterday, they likely needed water.
    # Bid slightly below their pressure to improve expected surplus.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        if trouble:
            # Still bid high enough to secure water, but cap below max pressure.
            target = min(budget, DAILY_SALARY * 0.92)
        else:
            # Underbid just a bit relative to yesterday's max.
            target = min(budget, highest_prev_bid - 1.0)
            # Ensure we don't bid too low when supply is tight.
            if supply <= (MIN_SUPPLY + 1.0):
                target = max(target, DAILY_SALARY * 0.55)
    else:
        # Opponents were not desperate; bid enough to win our requirement.
        if trouble:
            target = DAILY_SALARY * 0.8
        else:
            # If supply is tight, raise bid; if abundant, moderate.
            if supply <= (MIN_SUPPLY + 1.0):
                target = max(highest_prev_bid + 1.0, DAILY_SALARY * 0.6)
            else:
                target = max(highest_prev_bid + 0.5, DAILY_SALARY * 0.5)

    # Convert target into a safe bid within budget.
    target = float(target)
    if target < 0.0:
        target = 0.0
    if budget <= 0.0:
        return 0.0

    # Additional safeguard: if supply is extremely low relative to our requirement,
    # we should commit more; otherwise avoid overpaying.
    # (We don't know allocation rule, so we only modulate bid strength.)
    if supply < float(WATER_REQ):
        target = max(target, DAILY_SALARY * 0.75)

    return max(0.0, min(budget, target))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # Use previous_trace from any opponent to gauge competition
    highest_prev_bid = 0
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            bid_val = prev['bid']
            if bid_val > highest_prev_bid:
                highest_prev_bid = bid_val

    # Day 1 or no traces: base bid on HP
    if highest_prev_bid == 0:
        if my_status['hp'] <= 2:
            # Very low HP: need water
            bid = min(my_status['budget'], DAILY_SALARY * 0.9)
        elif my_status['hp'] <= 4:
            bid = min(my_status['budget'], DAILY_SALARY * 0.6)
        else:
            bid = min(my_status['budget'], DAILY_SALARY * 0.35)
        return max(0, int(bid))

    # Subsequent days: react to highest previous bid
    # If we are healthy and they bid high, reduce bid to save budget
    if my_status['hp'] > 3 and highest_prev_bid >= DAILY_SALARY * 0.8:
        bid = min(my_status['budget'], DAILY_SALARY * 0.3)
    elif my_status['hp'] <= 2:
        # Desperate: overbid slightly to secure water
        bid = min(my_status['budget'], max(DAILY_SALARY * 0.9, highest_prev_bid + 1.5))
    else:
        # Normal: try to underbid but still win if possible
        bid = min(my_status['budget'], max(DAILY_SALARY * 0.5, highest_prev_bid + 0.5))

    return max(0, int(bid))
